 it('test MCP connection → show the complete read-only report for the draft board URL',()=>{
  const labels=['Board URL','Authentication','MCP compatibility','Board access','Sprint access','Sprint issues','Workspace issue search'];
  cy.intercept('POST','/__rpc/mcp.test',request=>{
   expect(request.body.boardUrl).eq('https://example.atlassian.net/boards/77');expect(request.body.hostId).match(/^test-host-/);
   request.reply({ok:true,steps:labels.map(label=>({label,state:'passed',message:`Verified ${label}`}))});
  }).as('testMcp');
  mount(<Harness transport="mcp"/>);button('Settings').click();
  cy.get('[aria-label="Jira board URL"]').clear().type('https://example.atlassian.net/boards/77');
  button('Test connection').scrollIntoView().click();cy.wait('@testMcp');
  cy.contains('Read connection verified').scrollIntoView().should('be.visible');
  for(const label of labels)cy.contains(`Verified ${label}`).should('exist');
  cy.contains('Read-only check of the values above. Settings are not saved.').should('exist');
  cy.get('[aria-label="Atlassian MCP connection"]').then($el=>expect($el[0].getBoundingClientRect().right).at.most(width));
  cy.contains('Settings saved.').should('not.exist');
  cy.get('[aria-label="Jira board URL"]').scrollIntoView().clear().type('https://example.atlassian.net/boards/88');
  cy.contains('Read connection verified').should('not.exist');
 });
